    'content-type': 'application/json'
  },
  body: {
    rule_type: 'NAMING',
    asset_type_ids: ['string'],
    trigger_fields: ['string'],
    conditions: {schema_version: 0, root: {}},
    is_active: true,
    message: 'string'
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Put,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/assets/settings/field_rules/grouped/%7Brule_group_id%7D"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
    Content = new StringContent("{\"rule_type\":\"NAMING\",\"asset_type_ids\":[\"string\"],\"trigger_fields\":[\"string\"],\"conditions\":{\"schema_version\":0,\"root\":{}},\"is_active\":true,\"message\":\"string\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

